package httpapi

import (
	"archive/zip"
	"encoding/json"
	"fmt"
	"net/http"
	"path"
	"strings"
	"time"

	"github.com/google/uuid"
)

// Exporting a whole workspace.
//
// Documents could only be taken out one at a time. Handing a department over,
// answering an audit, keeping a copy before a workspace is wound up — all of
// them meant clicking through every document, and none of them were things
// anyone actually did.

// maxWorkspaceExport bounds one archive. A workspace larger than this is a
// migration rather than a download, and building it would hold a request open
// long past anything a browser will wait for.
const maxWorkspaceExport = 2000

// workspaceManifestName is the index of the archive — what every document in it
// is called, who owns it and when it was last touched. The name is fixed so a
// reader knows where to look, which also makes it a name a document may not
// take.
const workspaceManifestName = "목록.md"

// exportWorkspace streams every document in a workspace as one archive.
func (s *Server) exportWorkspace(w http.ResponseWriter, r *http.Request) {
	workspaceID, ok := pathUUID(w, r, "id")
	if !ok {
		return
	}
	p, _ := principalFrom(r.Context())
	// Taking a copy of everything is a decision about the whole workspace, so
	// it belongs to whoever administers it.
	if !s.workspaceManager(r.Context(), workspaceID, p.User) {
		writeError(w, 403, "WORKSPACE_PERMISSION_DENIED", "워크스페이스를 내보낼 권한이 없습니다.")
		return
	}

	format := strings.ToLower(strings.TrimSpace(r.URL.Query().Get("format")))
	if format == "" {
		format = "md"
	}
	if !contains([]string{"md", "html", "txt"}, format) {
		// The heavier formats are left out on purpose: a thousand documents
		// through Chromium is not a download, and DOCX would mean holding
		// every rendered file while the archive is built.
		writeError(w, 400, "UNSUPPORTED_EXPORT", "워크스페이스 내보내기는 md, html, txt를 지원합니다.")
		return
	}
	includeTrash := r.URL.Query().Get("trash") == "true"

	var workspaceName string
	if err := s.db.QueryRow(r.Context(), `SELECT name FROM workspaces WHERE id=$1`, workspaceID).Scan(&workspaceName); err != nil {
		writeError(w, 404, "WORKSPACE_NOT_FOUND", "워크스페이스를 찾을 수 없습니다.")
		return
	}

	// The document id ends the ordering because folder and title together do not
	// tell these rows apart. Sharing a title is the ordinary case rather than the
	// exception: createDocument names every untitled document 제목 없는 문서, so
	// in a workspace where nobody has renamed anything every row is tied with
	// every other. PostgreSQL promises nothing about the order of tied rows —
	// this sorts them with a quicksort, and the order it hands back follows the
	// order the rows came off the heap, which moves whenever a row is rewritten.
	//
	// What hangs on that order is which document keeps 제목 없는 문서.md and which
	// uniqueEntryName moves to 제목 없는 문서 (2).md, and which documents fall
	// outside the maxWorkspaceExport cut. Downloading an unchanged workspace
	// twice could therefore swap the contents of those two files and swap the
	// authors 목록.md credits them to. The id is unique, so adding it leaves no
	// tie for any of that to turn on.
	rows, err := s.db.Query(r.Context(), `
		SELECT d.id, d.title, d.content_json, d.folder_id, d.updated_at, d.deleted_at, u.display_name, d.page_orientation
		FROM documents d JOIN users u ON u.id = d.owner_id
		WHERE d.workspace_id = $1 AND ($2 OR d.deleted_at IS NULL)
		ORDER BY d.folder_id NULLS FIRST, d.title, d.id
		LIMIT $3`, workspaceID, includeTrash, maxWorkspaceExport+1)
	if err != nil {
		writeError(w, 500, "DATABASE_ERROR", "문서를 불러오지 못했습니다.")
		return
	}
	type exportItem struct {
		id       uuid.UUID
		title    string
		content  json.RawMessage
		folderID *uuid.UUID
		updated  time.Time
		trashed  bool
		owner    string
		// A document turned sideways stays turned in a bulk export; the
		// alternative is a zip where the wide tables are the ones cut off.
		landscape bool
	}
	items := make([]exportItem, 0, 64)
	for rows.Next() {
		var item exportItem
		var deleted *time.Time
		var orientation string
		if rows.Scan(&item.id, &item.title, &item.content, &item.folderID,
			&item.updated, &deleted, &item.owner, &orientation) == nil {
			item.landscape = orientation == "LANDSCAPE"
			item.trashed = deleted != nil
			items = append(items, item)
		}
	}
	rows.Close()
	if err := rows.Err(); err != nil {
		writeError(w, 500, "DATABASE_ERROR", "문서를 불러오지 못했습니다.")
		return
	}

	// Read one document beyond the cap to distinguish a full archive from an
	// incomplete one. The extra row is evidence of an omission, not an entry:
	// trim it before counting, rendering or recording the exported documents.
	truncated := len(items) > maxWorkspaceExport
	if truncated {
		items = items[:maxWorkspaceExport]
	}

	folders, err := s.folderPaths(r, workspaceID)
	if err != nil {
		writeError(w, 500, "DATABASE_ERROR", "폴더를 불러오지 못했습니다.")
		return
	}

	// The headers go out before the first document is rendered: the archive is
	// written straight to the connection so a large workspace never has to fit
	// in memory or on disk.
	//
	// This was the last route naming its download only in the quoted-string,
	// and a workspace name is checked for length alone — so one double quote in
	// a name ended the parameter where it stood and a parser threw the whole
	// header out. The name travels in `filename*` with the rest of them now,
	// and the fallback keeps just the day, which is ASCII whatever the name is.
	day := time.Now().Format("20060102")
	w.Header().Set("Content-Type", "application/zip")
	w.Header().Set("Content-Disposition", fmt.Sprintf(`attachment; filename="workspace-%s.zip"; filename*=UTF-8''%s-%s.zip`,
		day, extValueEscape(safeFilename(workspaceName)), day))
	w.Header().Set("X-Content-Type-Options", "nosniff")

	archive := zip.NewWriter(w)
	defer archive.Close()

	// The index is an entry in the same archive, so it takes part in the same
	// bookkeeping the documents do. It is written last, which is exactly why it
	// has to be claimed first: a document titled 목록 at the root of a workspace
	// exported as md produced a second entry under this very name, and an
	// unpacker writing entries in the order it finds them keeps one file where
	// there should be two — the same quiet loss uniqueEntryName was written to
	// prevent, arriving from the one name that never went through it. Claiming
	// it here moves the document to `목록 (2).md` and leaves the index where
	// every reader of this archive expects it. Nothing else shifts: the name is
	// at the archive root, so 목록 inside a folder is not a clash, and under
	// html or txt a document never reaches this name at all.
	used := map[string]bool{entryKey(workspaceManifestName): true}
	var manifest strings.Builder
	fmt.Fprintf(&manifest, "# %s\n\n내보낸 시각: %s\n문서 %d건\n\n",
		workspaceName, time.Now().Format(time.RFC3339), len(items))

	for _, item := range items {
		body := ""
		switch format {
		case "md":
			body = renderMarkdown(item.title, item.content)
		case "html":
			body = fullHTML(item.title, item.landscape, renderHTML(item.content))
		case "txt":
			body = renderPlainText(item.title, item.content)
		}

		directory := folders[folderKey(item.folderID)]
		if item.trashed {
			// The trash is kept apart, so restoring an archive does not put
			// deleted documents back among the live ones.
			directory = path.Join("휴지통", directory)
		}
		name := uniqueEntryName(used, directory, safeFilename(item.title), format)

		entry, err := archive.Create(name)
		if err != nil {
			// The response has begun, so there is nowhere to report this but
			// the log; the archive ends where it ends.
			s.logger.Warn("workspace export entry failed", "document", item.id, "error", err)
			return
		}
		if _, err := entry.Write([]byte(body)); err != nil {
			s.logger.Warn("workspace export write failed", "document", item.id, "error", err)
			return
		}
		fmt.Fprintf(&manifest, "- %s — %s, %s\n", name, item.owner, item.updated.Format("2006-01-02"))
	}

	if truncated {
		fmt.Fprintf(&manifest, "\n문서가 %d건을 넘어 그만큼만 담았습니다.\n", maxWorkspaceExport)
	}
	if entry, err := archive.Create(workspaceManifestName); err == nil {
		_, _ = entry.Write([]byte(manifest.String()))
	}

	s.audit(r, &p.User.ID, "EXPORT_WORKSPACE", "WORKSPACE", &workspaceID,
		map[string]any{"format": format, "documents": len(items)})
}

// folderPaths reads the workspace's folders as directory paths, so the archive
// comes out arranged the way the workspace is.
func (s *Server) folderPaths(r *http.Request, workspaceID uuid.UUID) (map[string]string, error) {
	// The order matters now that a second folder of one name is given a
	// suffix: a map iteration would hand that suffix to a different folder on
	// every request, so the same workspace downloaded twice would come out
	// arranged two different ways.
	rows, err := s.db.Query(r.Context(),
		`SELECT id, parent_id, name FROM folders WHERE workspace_id=$1 AND deleted_at IS NULL ORDER BY name, id`, workspaceID)
	if err != nil {
		return nil, err
	}
	defer rows.Close()

	type folder struct {
		parent *uuid.UUID
		name   string
	}
	all := map[uuid.UUID]folder{}
	// The query's order survives only in a slice; `all` is for the parent
	// lookups resolve makes, and ranging a map would throw the order away
	// again.
	order := make([]uuid.UUID, 0, 16)
	for rows.Next() {
		var id uuid.UUID
		var parent *uuid.UUID
		var name string
		if rows.Scan(&id, &parent, &name) == nil {
			all[id] = folder{parent: parent, name: name}
			order = append(order, id)
		}
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}

	paths := map[string]string{"": ""}
	// Two folders are allowed to carry one name — the check on a folder name
	// looks at emptiness and length alone, nothing at its siblings — and
	// path.Join then hands both of them the same directory string. The archive
	// has no way to say "two directories spelled alike", so the two folders a
	// user was looking at unpack as one and the arrangement they were
	// downloading is gone; the documents survive only because uniqueEntryName
	// moves the second of two equal file names aside. So a directory is
	// claimed here as it is built, and a folder arriving at a name another
	// folder already took steps to `기획 (2)` — the same move, one level up.
	//
	// The claim is keyed through entryKey for the reason the entry names are:
	// the archive is unpacked on whatever machine downloaded it, and on
	// Windows — the deployment target — `Report` and `report` are one
	// directory. Only the key is folded; the path this returns, and that the
	// archive and the user then carry, keeps the casing the folder was given.
	claimed := map[string]bool{}
	var resolve func(id uuid.UUID, depth int) string
	resolve = func(id uuid.UUID, depth int) string {
		if existing, ok := paths[id.String()]; ok {
			return existing
		}
		// Depth is bounded in case the data ever contains a cycle: a lost
		// branch is better than a request that never returns.
		if depth > 32 {
			return ""
		}
		entry, ok := all[id]
		if !ok {
			return ""
		}
		prefix := ""
		if entry.parent != nil {
			prefix = resolve(*entry.parent, depth+1)
		}
		segment := safeFolderSegment(entry.name)
		result := path.Join(prefix, segment)
		for suffix := 2; claimed[entryKey(result)]; suffix++ {
			result = path.Join(prefix, fmt.Sprintf("%s (%d)", segment, suffix))
		}
		claimed[entryKey(result)] = true
		paths[id.String()] = result
		return result
	}
	for _, id := range order {
		resolve(id, 0)
	}
	return paths, nil
}

func folderKey(id *uuid.UUID) string {
	if id == nil {
		return ""
	}
	return id.String()
}

// safeFolderSegment turns a folder name into one element of an archive path.
//
// safeFilename already takes the separators out, so what comes back can only be
// a single element — except for the two names every path reader treats as
// navigation. A folder called `..` walks the entry out of the archive root
// (`../문서.md`, which a naive unpacker writes outside the target directory),
// and both `.` and `..` fold the folder into its parent, so a trashed document
// lands back among the live ones and two different folders become one. Prefixing
// those two leaves every other name — Korean, spaces, dots anywhere else —
// exactly as safeFilename left it.
func safeFolderSegment(name string) string {
	safe := safeFilename(name)
	if safe == "." || safe == ".." {
		return "_" + safe
	}
	return safe
}

// entryKey is how one archive entry name is compared with another.
//
// Not byte for byte: the archive is unpacked on whatever machine downloaded it,
// and on Windows — the deployment target — as on macOS out of the box, a file
// name differing only in case is the same file name. So `Report.md` and
// `report.md` are two entries that an unpacker writing them in order turns into
// one file, which is precisely the quiet loss of a document uniqueEntryName
// exists to prevent. Folding the case here is the only thing this affects: the
// name that goes into the archive, and that a user then sees, keeps every
// letter as it was typed.
func entryKey(name string) string {
	return strings.ToLower(name)
}

// uniqueEntryName keeps two documents with the same title from becoming one
// file in the archive, which is how an export quietly loses a document.
func uniqueEntryName(used map[string]bool, directory, base, extension string) string {
