 func TestTwoTitlesDifferingOnlyInCaseStayTwoEntries(t *testing.T) {
 	// The archive is unpacked wherever it is downloaded, and the deployment
 	// target is Windows — where `Report.md` and `report.md` are one file name.
package httpapi

import (
	"context"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"testing"

	"github.com/hkjang/muni/internal/pdfx"
)

// TestDevtoolsPDFHasPageNumbers renders a document long enough to need three
// pages and checks that the footer Chromium drew is really there.
//
// It needs a browser, so it skips where there is not one. Everything about
// this path is the conversation with Chromium; a test with the browser stubbed
// out would only be testing the stub.
func TestDevtoolsPDFHasPageNumbers(t *testing.T) {
	binary, err := chromiumBinary()
	if err != nil {
		t.Skip("no headless browser available")
	}

	// A browser installed as a snap cannot read /tmp, which is where a Go test
	// puts its scratch directory. The container ships an ordinary package and
	// has no such confinement, so this is about where the test runs rather
	// than about muni.
	tempDir, err := os.MkdirTemp(os.Getenv("HOME"), "muni-pdf-test-")
	if err != nil {
		t.Skip("no writable home directory for the browser to read from")
	}
	t.Cleanup(func() { _ = os.RemoveAll(tempDir) })
	htmlPath := filepath.Join(tempDir, "document.html")
	// The content is deliberately ASCII. A machine without the CJK fonts the
	// container ships renders Korean as empty boxes, and what this test is
	// checking is the pagination and the footer, not the fonts.
	const title = "muni page numbering"
	var body strings.Builder
	for page := 1; page <= 3; page++ {
		body.WriteString("<h1>Chapter " + strconv.Itoa(page) + "</h1>")
		for line := 0; line < 45; line++ {
			body.WriteString("<p>A line of body text that goes on for a while. " +
				strings.Repeat("more words ", 6) + "</p>")
		}
	}
	if err := os.WriteFile(htmlPath, []byte(fullHTML(title, false, body.String())), 0600); err != nil {
		t.Fatal(err)
	}

	pdf, err := printToPDFWithDevtools(context.Background(), binary, tempDir, htmlPath,
		pdfFurniture{Title: title})
	if err != nil {
		t.Fatalf("devtools render failed: %v", err)
	}
	if len(pdf) == 0 {
		t.Fatal("the render produced nothing")
	}
	if !strings.HasPrefix(string(pdf), "%PDF-") {
		t.Fatal("the result is not a PDF")
	}

	// muni's own PDF reader is used to check the result, which proves the file
	// paginated and that the two halves agree about what a PDF is.
	parsed, err := pdfx.Import(context.Background(), pdf)
	if err != nil {
		t.Fatalf("muni could not read back the PDF it produced: %v", err)
	}
	if parsed.Pages < 2 {
		t.Fatalf("expected a document long enough to paginate, got %d page(s)", parsed.Pages)
	}
	// The footer is read off the page rather than out of the document: an
	// import drops the running head and the page number, which is what a
	// reader wants and the opposite of what this test is asking about.
	pageText, err := pdfx.PageTexts(context.Background(), pdf)
	if err != nil {
		t.Fatalf("muni could not read back the PDF it produced: %v", err)
	}
	first := ""
	if len(pageText) > 0 {
		first = pageText[0]
	}
	if !strings.Contains(first, "1 / "+strconv.Itoa(parsed.Pages)) {
		t.Fatalf("the page numbering is not on the page: %q", truncate(first, 300))
	}
	if !strings.Contains(first, title) {
		t.Fatalf("the footer should name the document: %q", truncate(first, 300))
	}
	// And the import leaves it out of the document, which is the other half
	// of the same contract.
	if body := parsed.Document.PlainText(); strings.Contains(body, "1 / "+strconv.Itoa(parsed.Pages)) {
		t.Errorf("the page number was imported as text: %q", truncate(body, 200))
	}
	t.Logf("rendered %d pages, %d bytes", parsed.Pages, len(pdf))
}

