		{"tagging", "PUT", "/api/v1/documents/{id}/tags", `{"tags":["가로채기"]}`},
		{"moving", "POST", "/api/v1/documents/{id}/move", `{"folderId":null}`},
		{"suggesting an edit", "POST", "/api/v1/documents/{id}/suggestions", `{"body":"제안"}`},
	}

